};

export const InterstitialAd: React.FC<{ isOpen: boolean; onClose: () => void }> = ({ isOpen, onClose }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center p-6 text-white animate-in fade-in duration-300">
      <div className="absolute top-4 right-4">
        <button 
          onClick={onClose}
          className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center hover:bg-white/20 transition-colors"
        >
          <span className="material-icons-round">close</span>
        </button>
      </div>
      <div className="text-center">
        <div className="w-16 h-16 bg-blue-500 rounded-2xl mx-auto mb-6 flex items-center justify-center shadow-lg shadow-blue-500/20">
          <span className="material-icons-round text-3xl">play_arrow</span>
        </div>
        <h2 className="text-2xl font-bold mb-2">MyNote Premium</h2>
        <p className="text-white/60 mb-8 max-w-xs mx-auto text-sm">
          Remove ads and get 10GB cloud storage with our Premium plan.
        </p>
