import React, { useState } from 'react';

interface AuthProps {
  onLogin: (email: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (email && password) {
      onLogin(email);
    } else {
      alert('Please fill in all fields');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 p-6 transition-colors">
      <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-3xl p-8 shadow-2xl border border-slate-200 dark:border-slate-800">
        <div className="flex flex-col items-center mb-8">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white mb-4 shadow-xl shadow-indigo-600/20">
            <span className="material-icons-round text-3xl">edit_note</span>
          </div>
          <h1 className="text-2xl font-bold text-slate-800 dark:text-white">MyNote</h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">
            {isLogin ? 'Welcome back!' : 'Create your account'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 ml-1">Email Address</label>
            <input 
              type="email" 
              className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all dark:text-white"
              placeholder="name@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 ml-1">Password</label>
            <input 
              type="password" 
              className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all dark:text-white"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button 
            type="submit"
            className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-lg shadow-indigo-600/30 hover:bg-indigo-700 active:scale-95 transition-all mt-4"
          >
            {isLogin ? 'Sign In' : 'Sign Up'}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button 
            onClick={() => setIsLogin(!isLogin)}
            className="text-indigo-600 dark:text-indigo-400 text-sm font-medium hover:underline"
          >
            {isLogin ? "Don't have an account? Sign Up" : 'Already have an account? Sign In'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useMemo } from 'react';
import { Note, NoteTag } from '../types';
import { Icons, TAG_COLORS } from '../constants';

interface DashboardProps {
  notes: Note[];
  onAddNote: () => void;
  onEditNote: (note: Note) => void;
  onDeleteNote: (id: string) => void;
  onLogout: () => void;
  toggleTheme: () => void;
  currentTheme: 'light' | 'dark';
}

const Dashboard: React.FC<DashboardProps> = ({ 
  notes, onAddNote, onEditNote, onDeleteNote, onLogout, toggleTheme, currentTheme 
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTag, setActiveTag] = useState<NoteTag | 'All'>('All');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredNotes = useMemo(() => {
    return notes
      .filter(note => {
        const matchesSearch = note.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              note.content.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesTag = activeTag === 'All' || note.tags.includes(activeTag as NoteTag);
        return matchesSearch && matchesTag;
      })
      .sort((a, b) => b.updatedAt - a.updatedAt);
  }, [notes, searchQuery, activeTag]);

  const tags: (NoteTag | 'All')[] = ['All', 'Work', 'Personal', 'Ideas', 'Urgent'];

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 transition-colors">
      {/* Header */}
      <header className="p-4 sm:p-6 pb-2 space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-600/20">
              <span className="material-icons-round">edit_note</span>
            </div>
            <h1 className="text-2xl font-bold tracking-tight text-slate-800 dark:text-white">MyNote</h1>
          </div>
          <div className="flex items-center space-x-2">
            <button 
              onClick={toggleTheme}
              className="p-2 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
            >
              {currentTheme === 'light' ? <Icons.Dark /> : <Icons.Light />}
            </button>
            <button 
              onClick={onLogout}
              className="p-2 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
            >
              <Icons.Logout />
            </button>
          </div>
        </div>

        {/* Search & Filters */}
        <div className="flex flex-col sm:flex-row space-y-3 sm:space-y-0 sm:space-x-3">
          <div className="flex-1 relative">
            <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none text-slate-400">
              <Icons.Search />
            </div>
            <input 
              type="text" 
              placeholder="Search notes..."
              className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all dark:text-white"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="flex space-x-2 overflow-x-auto pb-2 sm:pb-0 scrollbar-hide">
            {tags.map(tag => (
              <button
                key={tag}
                onClick={() => setActiveTag(tag)}
                className={`px-4 py-2 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${
                  activeTag === tag 
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/20' 
                  : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'
                }`}
              >
                {tag}
              </button>
            ))}
          </div>
        </div>
      </header>

      {/* Main View Toggle & Count */}
      <div className="px-4 sm:px-6 py-2 flex items-center justify-between">
        <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{filteredNotes.length} Notes</span>
        <button 
          onClick={() => setViewMode(viewMode === 'grid' ? 'list' : 'grid')}
          className="p-1 rounded-lg bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400"
        >
          {viewMode === 'grid' ? <Icons.List /> : <Icons.Grid />}
        </button>
      </div>

      {/* Content */}
      <main className="flex-1 overflow-y-auto px-4 sm:px-6 pb-24">
        {filteredNotes.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center opacity-50 space-y-4">
            <span className="material-icons-round text-6xl text-slate-300">note_stack</span>
            <p className="text-slate-500 dark:text-slate-400">No notes found.<br/>Start writing something amazing!</p>
          </div>
        ) : (
          <div className={viewMode === 'grid' ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4" : "space-y-3"}>
            {filteredNotes.map(note => (
              <NoteCard 
                key={note.id} 
                note={note} 
                onClick={() => onEditNote(note)}
                onDelete={() => onDeleteNote(note.id)}
                isList={viewMode === 'list'}
              />
            ))}
          </div>
        )}
      </main>

      {/* FAB */}
      <button 
        onClick={onAddNote}
        className="fixed right-6 bottom-24 w-16 h-16 bg-indigo-600 rounded-full flex items-center justify-center text-white shadow-2xl shadow-indigo-600/40 hover:scale-110 active:scale-90 transition-all z-20 group"
      >
        <span className="material-icons-round text-3xl group-hover:rotate-90 transition-transform">add</span>
      </button>
    </div>
  );
};

interface NoteCardProps {
  note: Note;
  onClick: () => void;
  onDelete: () => void;
  isList?: boolean;
}

const NoteCard: React.FC<NoteCardProps> = ({ note, onClick, onDelete, isList }) => {
  const [isDeleting, setIsDeleting] = useState(false);
  const [touchStart, setTouchStart] = useState<number | null>(null);

  // Swipe-to-delete logic simulation (simple swipe check)
  const handleTouchStart = (e: React.TouchEvent) => setTouchStart(e.touches[0].clientX);
  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStart !== null) {
      const touchEnd = e.changedTouches[0].clientX;
      if (touchStart - touchEnd > 100) { // Swiped left
        if (confirm("Delete this note?")) onDelete();
      }
    }
  };

  const handleLongPress = (e: React.MouseEvent | React.TouchEvent) => {
    // Basic long press simulation context menu
  };

  return (
    <div 
      className={`group bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden cursor-pointer transition-all hover:border-indigo-500/50 dark:hover:border-indigo-400/30 hover:shadow-xl relative ${isList ? 'p-4 flex items-center' : 'p-5'}`}
      onClick={onClick}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onContextMenu={(e) => {
        e.preventDefault();
        if (confirm("Delete this note?")) onDelete();
      }}
    >
      <div className={isList ? "flex-1 mr-4" : "mb-3"}>
        <div className="flex items-center justify-between mb-1">
          <h3 className="font-bold text-lg text-slate-800 dark:text-white truncate pr-6">{note.title || 'Untitled'}</h3>
          {!isList && (
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(); }}
              className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 p-1 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 transition-all"
            >
              <Icons.Delete />
            </button>
          )}
        </div>
        <p className={`text-slate-500 dark:text-slate-400 text-sm overflow-hidden ${isList ? 'line-clamp-1' : 'line-clamp-3'}`}>
          {note.content || 'No content yet...'}
        </p>
      </div>

      <div className={`flex flex-wrap gap-2 items-center justify-between ${isList ? 'flex-shrink-0 flex-col items-end gap-1' : 'mt-4 pt-4 border-t border-slate-100 dark:border-slate-800'}`}>
        <div className="flex flex-wrap gap-1">
          {note.tags.map(tag => (
            <span key={tag} className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${TAG_COLORS[tag]}`}>
              {tag}
            </span>
          ))}
        </div>
        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">
          {new Date(note.updatedAt).toLocaleDateString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
        </span>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { Note, NoteTag } from '../types';
import { Icons, TAG_COLORS } from '../constants';

interface EditorProps {
  note: Note;
  onSave: (updatedNote: Note) => void;
  onBack: () => void;
}

const Editor: React.FC<EditorProps> = ({ note, onSave, onBack }) => {
  const [title, setTitle] = useState(note.title);
  const [content, setContent] = useState(note.content);
  const [tags, setTags] = useState<NoteTag[]>(note.tags);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<number>(note.updatedAt);

  // Auto-save logic
  useEffect(() => {
    const timeout = setTimeout(() => {
      if (title !== note.title || content !== note.content || JSON.stringify(tags) !== JSON.stringify(note.tags)) {
        handleSave();
      }
    }, 2000); // Save after 2 seconds of inactivity

    return () => clearTimeout(timeout);
  }, [title, content, tags]);

  const handleSave = useCallback(() => {
    setIsSaving(true);
    const updatedNote: Note = {
      ...note,
      title,
      content,
      tags,
      updatedAt: Date.now()
    };
    onSave(updatedNote);
    setLastSaved(Date.now());
    setTimeout(() => setIsSaving(false), 800);
  }, [title, content, tags, note, onSave]);

  const toggleTag = (tag: NoteTag) => {
    setTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const availableTags: NoteTag[] = ['Work', 'Personal', 'Ideas', 'Urgent'];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-950 transition-colors animate-in slide-in-from-right duration-300">
      {/* Editor Header */}
      <header className="px-4 py-4 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center space-x-2">
          <button 
            onClick={() => { handleSave(); onBack(); }}
            className="p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-400 transition-colors"
          >
            <Icons.Back />
          </button>
          <div className="flex flex-col">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">Status</span>
            <span className="text-xs font-medium text-slate-600 dark:text-slate-300">
              {isSaving ? 'Saving...' : `Saved at ${new Date(lastSaved).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`}
            </span>
          </div>
        </div>
        <button 
          onClick={() => { handleSave(); onBack(); }}
          className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-indigo-600/20 hover:bg-indigo-700 active:scale-95 transition-all"
        >
          Done
        </button>
      </header>

      {/* Editor Body */}
      <main className="flex-1 flex flex-col p-6 space-y-4 max-w-4xl mx-auto w-full">
        {/* Title Input */}
        <input 
          type="text"
          placeholder="Note Title"
          className="text-3xl sm:text-4xl font-black bg-transparent border-none focus:ring-0 placeholder:text-slate-200 dark:placeholder:text-slate-800 dark:text-white w-full"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />

        {/* Tags Selector */}
        <div className="flex items-center space-x-2 py-2 overflow-x-auto scrollbar-hide">
          <Icons.Tag />
          {availableTags.map(tag => (
            <button
              key={tag}
              onClick={() => toggleTag(tag)}
              className={`px-3 py-1 rounded-full text-[11px] font-bold uppercase transition-all whitespace-nowrap ${
                tags.includes(tag) 
                ? TAG_COLORS[tag] 
                : 'bg-slate-100 dark:bg-slate-900 text-slate-400 hover:bg-slate-200'
              }`}
            >
              {tag}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <textarea 
          placeholder="Start typing your thoughts..."
          className="flex-1 w-full bg-transparent border-none focus:ring-0 resize-none text-lg text-slate-700 dark:text-slate-300 placeholder:text-slate-200 dark:placeholder:text-slate-800 leading-relaxed min-h-[50vh]"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
      </main>
    </div>
  );
};

export default Editor;

import React, { useState, useEffect, useCallback } from 'react';
import { Note, User, AppState } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import Editor from './components/Editor';
import { BannerAd, InterstitialAd } from './components/AdPlaceholders';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('mynote_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [notes, setNotes] = useState<Note[]>(() => {
    const saved = localStorage.getItem('mynote_notes');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('mynote_theme');
    return (saved as 'light' | 'dark') || 'light';
  });

  const [activeNote, setActiveNote] = useState<Note | null>(null);
  const [showInterstitial, setShowInterstitial] = useState(false);

  // Sync state to LocalStorage (Simulated cloud sync)
  useEffect(() => {
    localStorage.setItem('mynote_notes', JSON.stringify(notes));
    localStorage.setItem('mynote_user', JSON.stringify(currentUser));
    localStorage.setItem('mynote_theme', theme);

    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [notes, currentUser, theme]);

  const handleLogin = (email: string) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      email,
      name: email.split('@')[0]
    };
    setCurrentUser(newUser);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveNote(null);
  };

  const handleAddNote = () => {
    const newNote: Note = {
      id: Date.now().toString(),
      title: '',
      content: '',
      tags: [],
      updatedAt: Date.now(),
      createdAt: Date.now(),
      userId: currentUser?.id || 'anonymous'
    };
    // setNotes([newNote, ...notes]); // Don't add to list until editor opens? 
    // Actually common practice in mobile is to create and then go to editor.
    setActiveNote(newNote);
  };

  const handleSaveNote = useCallback((updatedNote: Note) => {
    setNotes(prevNotes => {
      const exists = prevNotes.find(n => n.id === updatedNote.id);
      if (exists) {
        return prevNotes.map(n => n.id === updatedNote.id ? updatedNote : n);
      } else {
        return [updatedNote, ...prevNotes];
      }
    });
  }, []);

  const handleDeleteNote = (id: string) => {
    setNotes(notes.filter(n => n.id !== id));
    // Trigger Ad when deleting
    setShowInterstitial(true);
  };

  const handleCloseEditor = () => {
    setActiveNote(null);
    // Trigger Ad when finishing a note session
    setShowInterstitial(true);
  };

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  if (!currentUser) {
    return <Auth onLogin={handleLogin} />;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-white dark:bg-slate-950 transition-colors">
      <div className="flex-1 overflow-hidden">
        {activeNote ? (
          <Editor 
            note={activeNote} 
            onSave={handleSaveNote} 
            onBack={handleCloseEditor}
          />
        ) : (
          <Dashboard 
            notes={notes}
            onAddNote={handleAddNote}
            onEditNote={setActiveNote}
            onDeleteNote={handleDeleteNote}
            onLogout={handleLogout}
            toggleTheme={toggleTheme}
            currentTheme={theme}
