import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Note, NoteTag } from '../types';
import { Icons, TAG_COLORS } from '../constants';

interface EditorProps {
  note: Note;
  onSave: (updatedNote: Note) => void;
  onBack: () => void;
}

const Editor: React.FC<EditorProps> = ({ note, onSave, onBack }) => {
  const [title, setTitle] = useState(note.title);
  const [content, setContent] = useState(note.content);
  const [tags, setTags] = useState<NoteTag[]>(note.tags);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<number>(note.updatedAt);

  const initialLoad = useRef(true);

  const handleSave = useCallback(() => {
    setIsSaving(true);
    const updatedNote: Note = {
      ...note,
      title,
      content,
      tags,
      updatedAt: Date.now()
    };
    onSave(updatedNote);
    setLastSaved(Date.now());
    setTimeout(() => setIsSaving(false), 500);
  }, [title, content, tags, note, onSave]);

  // Auto-save logic
  useEffect(() => {
    if (initialLoad.current) {
      initialLoad.current = false;
      return;
    }

    const timeout = setTimeout(() => {
      const hasChanges = title !== note.title || content !== note.content || JSON.stringify(tags) !== JSON.stringify(note.tags);
      if (hasChanges) {
        handleSave();
      }
    }, 1500);

    return () => clearTimeout(timeout);
  }, [title, content, tags, note.title, note.content, note.tags, handleSave]);

  const toggleTag = (tag: NoteTag) => {
    setTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const availableTags: NoteTag[] = ['Work', 'Personal', 'Ideas', 'Urgent'];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-950 transition-colors animate-in slide-in-from-right duration-300">
      {/* Editor Header */}
      <header className="px-4 py-3 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center space-x-3">
          <button 
            onClick={() => { handleSave(); onBack(); }}
            className="p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-400 transition-colors"
          >
            <Icons.Back />
          </button>
          <div className="flex flex-col">
            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none">Auto-Sync</span>
            <span className="text-[11px] font-medium text-slate-500 dark:text-slate-400">
              {isSaving ? 'Saving changes...' : `Last edit: ${new Date(lastSaved).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`}
            </span>
          </div>
        </div>
        <button 
          onClick={() => { handleSave(); onBack(); }}
          className="px-5 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-md shadow-indigo-600/20 hover:bg-indigo-700 active:scale-95 transition-all"
        >
          Save & Exit
        </button>
      </header>

      {/* Editor Body */}
      <main className="flex-1 flex flex-col p-6 space-y-4 max-w-4xl mx-auto w-full overflow-y-auto">
        <input 
          type="text"
          placeholder="Title"
          className="text-3xl sm:text-4xl font-black bg-transparent border-none focus:ring-0 placeholder:text-slate-200 dark:placeholder:text-slate-800 dark:text-white w-full outline-none"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />

        <div className="flex items-center space-x-2 py-2 overflow-x-auto scrollbar-hide border-y border-slate-50 dark:border-slate-900">
          <Icons.Tag />
          {availableTags.map(tag => (
            <button
              key={tag}
              onClick={() => toggleTag(tag)}
              className={`px-3 py-1.5 rounded-full text-[10px] font-bold uppercase transition-all whitespace-nowrap ${
                tags.includes(tag) 
                ? TAG_COLORS[tag] 
                : 'bg-slate-50 dark:bg-slate-900 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'
              }`}
            >
              {tag}
            </button>
          ))}
        </div>

        <textarea 
          placeholder="Your story starts here..."
          className="flex-1 w-full bg-transparent border-none focus:ring-0 resize-none text-lg text-slate-700 dark:text-slate-300 placeholder:text-slate-200 dark:placeholder:text-slate-800 leading-relaxed outline-none"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
      </main>
    </div>
  );
};

export default Editor;

import React, { useState, useEffect, useCallback } from 'react';
import { Note, User } from './types';
import Dashboard from './components/Dashboard';
import Editor from './components/Editor';
import { BannerAd, InterstitialAd } from './components/AdPlaceholders';

const DEFAULT_USER: User = {
  id: 'local-user',
  email: 'user@mynote.local',
  name: 'Guest User'
};

const App: React.FC = () => {
  const [notes, setNotes] = useState<Note[]>(() => {
    const saved = localStorage.getItem('mynote_notes');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('mynote_theme');
    if (saved === 'dark' || saved === 'light') return saved;
    // Fallback to system preference if no saved theme
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [activeNote, setActiveNote] = useState<Note | null>(null);
  const [showInterstitial, setShowInterstitial] = useState(false);

  // Theme effect - must apply 'dark' class to html element
  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('mynote_theme', theme);
  }, [theme]);

  // Notes persistence effect
  useEffect(() => {
    localStorage.setItem('mynote_notes', JSON.stringify(notes));
  }, [notes]);

  // Global 60-second Interstitial Ad Timer
  useEffect(() => {
    const interval = setInterval(() => {
      // Don't interrupt if they are typing in the editor, or do interrupt? 
      // User requested "har 60 second me Ads dikhega" (Ad will show every 60s)
      setShowInterstitial(true);
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  const handleAddNote = () => {
    const newNote: Note = {
      id: Date.now().toString(),
      title: '',
      content: '',
      tags: [],
      updatedAt: Date.now(),
      createdAt: Date.now(),
      userId: DEFAULT_USER.id
    };
    setActiveNote(newNote);
  };

  const handleSaveNote = useCallback((updatedNote: Note) => {
    setNotes(prevNotes => {
      const existsIndex = prevNotes.findIndex(n => n.id === updatedNote.id);
      if (existsIndex !== -1) {
        const newNotes = [...prevNotes];
        newNotes[existsIndex] = updatedNote;
        return newNotes;
      } else {
        return [updatedNote, ...prevNotes];
      }
    });
  }, []);

  const handleDeleteNote = (id: string) => {
    if (confirm("Are you sure you want to delete this note?")) {
      setNotes(prev => prev.filter(n => n.id !== id));
    }
  };

  const handleCloseEditor = () => {
    setActiveNote(null);
  };

