          <div className={viewMode === 'grid' ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4" : "space-y-3"}>
            {filteredNotes.map(note => (
              <NoteCard 
                key={note.id} 
                note={note} 
                onClick={() => onEditNote(note)}
                onDelete={() => onDeleteNote(note.id)}
                onTagClick={(tag) => setActiveTag(tag)}
                isList={viewMode === 'list'}
              />
            ))}
          </div>
        )}
      </main>

      {/* FAB */}
      <button 
        onClick={onAddNote}
        className="fixed right-6 bottom-24 w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-2xl shadow-indigo-600/40 hover:scale-110 active:scale-95 transition-all z-20 group"
      >
        <span className="material-icons-round text-3xl group-hover:rotate-180 transition-transform duration-500">add</span>
      </button>
    </div>
  );
};

interface NoteCardProps {
  note: Note;
  onClick: () => void;
  onDelete: () => void;
  onTagClick: (tag: NoteTag) => void;
  isList?: boolean;
}

const NoteCard: React.FC<NoteCardProps> = ({ note, onClick, onDelete, onTagClick, isList }) => {
  return (
    <div 
      className={`group bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden cursor-pointer transition-all hover:border-indigo-500/50 dark:hover:border-indigo-400/30 hover:shadow-xl relative active:scale-[0.98] ${isList ? 'p-4 flex items-center' : 'p-5'}`}
      onClick={onClick}
    >
      <div className={isList ? "flex-1 mr-4 overflow-hidden" : "mb-3"}>
        <div className="flex items-center justify-between mb-1">
          <h3 className="font-bold text-lg text-slate-800 dark:text-white truncate pr-6">
            {note.title || <span className="text-slate-300 dark:text-slate-700 italic font-normal">Untitled Note</span>}
          </h3>
          <button 
            onClick={(e) => { 
              e.stopPropagation(); 
              onDelete(); 
            }}
            className={`p-2 rounded-xl text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-all z-10 ${isList ? 'ml-2' : 'absolute top-3 right-3 bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm'}`}
            title="Delete Note"
          >
            <Icons.Delete />
          </button>
        </div>
        <p className={`text-slate-500 dark:text-slate-400 text-sm overflow-hidden leading-relaxed ${isList ? 'line-clamp-1' : 'line-clamp-3'}`}>
          {note.content || <span className="text-slate-300 dark:text-slate-700 italic">No content...</span>}
        </p>
      </div>

      <div className={`flex flex-wrap gap-2 items-center justify-between ${isList ? 'flex-shrink-0 flex-col items-end gap-1' : 'mt-4 pt-4 border-t border-slate-50 dark:border-slate-800/50'}`}>
        <div className="flex flex-wrap gap-1">
          {note.tags.map(tag => (
            <span 
              key={tag} 
              onClick={(e) => { e.stopPropagation(); onTagClick(tag); }}
              className={`text-[9px] px-2 py-0.5 rounded-full font-black uppercase tracking-wider transition-transform hover:scale-110 active:scale-90 ${TAG_COLORS[tag]}`}
            >
              {tag}
            </span>
          ))}
        </div>
        <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
          {new Date(note.updatedAt).toLocaleDateString([], { month: 'short', day: 'numeric' })}
        </span>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { Note, User } from './types';
import Dashboard from './components/Dashboard';
import Editor from './components/Editor';
import { BannerAd, InterstitialAd } from './components/AdPlaceholders';

const DEFAULT_USER: User = {
  id: 'guest-user',
  email: 'guest@mynote.app',
  name: 'Guest'
};

const App: React.FC = () => {
  const [user] = useState<User>(() => {
    const saved = localStorage.getItem('mynote_user');
    return saved ? JSON.parse(saved) : DEFAULT_USER;
  });

  const [notes, setNotes] = useState<Note[]>(() => {
    const saved = localStorage.getItem('mynote_notes');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('mynote_theme');
    if (saved === 'dark' || saved === 'light') return saved;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [activeNote, setActiveNote] = useState<Note | null>(null);
  const [showInterstitial, setShowInterstitial] = useState(false);

  // Theme application
  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('mynote_theme', theme);
  }, [theme]);

  // Notes persistence
  useEffect(() => {
    localStorage.setItem('mynote_notes', JSON.stringify(notes));
  }, [notes]);

  // Global 60-second Interstitial Ad Timer
  useEffect(() => {
    const interval = setInterval(() => {
      setShowInterstitial(true);
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  const handleAddNote = () => {
    const newNote: Note = {
      id: Date.now().toString(),
      title: '',
      content: '',
      tags: ['Draft'],
      updatedAt: Date.now(),
      createdAt: Date.now(),
      userId: user.id
    };
    setActiveNote(newNote);
  };

  const handleSaveNote = useCallback((updatedNote: Note) => {
    setNotes(prevNotes => {
      const existsIndex = prevNotes.findIndex(n => n.id === updatedNote.id);
      if (existsIndex !== -1) {
        const newNotes = [...prevNotes];
        newNotes[existsIndex] = updatedNote;
        return newNotes;
      } else {
        return [updatedNote, ...prevNotes];
      }
    });
  }, []);

  const handleDeleteNote = (id: string) => {
    if (window.confirm("Delete this note permanently?")) {
      setNotes(prev => prev.filter(n => n.id !== id));
    }
  };

  const handleCloseEditor = () => {
    setActiveNote(null);
  };

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-white dark:bg-slate-950 transition-colors duration-300">
      <div className="flex-1 overflow-hidden relative">
        {activeNote ? (
          <Editor 
            note={activeNote} 
            onSave={handleSaveNote} 
            onBack={handleCloseEditor}
          />
        ) : (
          <Dashboard 
            notes={notes}
            onAddNote={handleAddNote}
            onEditNote={setActiveNote}
            onDeleteNote={handleDeleteNote}
            toggleTheme={toggleTheme}
            currentTheme={theme}
          />
        )}
      </div>

      {!activeNote && <BannerAd />}

      <InterstitialAd 
        isOpen={showInterstitial} 
        onClose={() => setShowInterstitial(false)} 
      />
    </div>
  );
};

